mapper.select:
select * from ( select a.FINPROD_ID finprodId, a.FINPROD_TYPE finprodType, a.FINPROD_TYPE2 finprodType2, a.FINPROD_MARKET_ID finprodMarketId, a.FINPROD_NAME finprodName, a.FINPROD_ABBR finprodAbbr, a.CALENDAR_ID calendarId, a.IDATE idate, a.CCY ccy, a.VDATE vdate, a.MDATE mdate, a.TRADE_MARKET tradeMarket, a.CAPI_INCOME_FEATURE capiIncomeFeature, a.MANAGER issuer, a.UPDATE_USER updateUser, a.UPDATE_TIME updateTime, /** modify by yanya on 20210324 基金类型存储在type1**/ /** b.TYPE_6 fundType,**/ b.TYPE_1 fundType, b.TYPE_7 secondType, /**added by wangguiqi on 2019/7/22 -start**/ b.TYPE_9 type9, b.TYPE_10 type10, b.TYPE_11 type11, b.TYPE_12 type12, /**added by wangguiqi on 2019/7/22 -end**/ c.IS_COMPOUND_INT isCompoundInt, c.DATA_SOURCE dataSource, d.CUSTOMER_NAME manager, f.PAY_TYPE divideMethod, f.PAY_CYCLE carryoverFreq,
(CASE WHEN C.PUR_SPEED is not null THEN 'T+'||C.PUR_SPEED ELSE '' END) purSpeed, (CASE WHEN C.RED_SPEED is not null THEN 'T+'||C.RED_SPEED ELSE '' END) redSpeed, c.TRM_FUND_TYPE trmFundType, c.TRM_FUND_ABBR trmFundAbbr, m.CALENDAR_NAME calendarName from FIN_PRODUCT a left join MST_CUSTOMER_INFO d on d.CUSTOMER_ID = a.MANAGER left join FIN_CASH_INFO e on a.FINPROD_ID = e.FINPROD_ID and e.CASH_TYPE_2 = #{CASH_TYPE_2,jdbcType=VARCHAR} and e.FINPROD_TYPE = #{FIN_CASH_BUSINESS_TYPE,jdbcType=VARCHAR} left join FIN_CASH_PAY_RULE f on e.CASH_ID = f.CASH_ID and a.VDATE = f.EFF_DATE left join FIN_PRODUCT_TYPE b on a.FINPROD_ID = b.FINPROD_ID left join FIN_PRODUCT_ADD c on a.FINPROD_ID = c.FINPROD_ID left join MST_CALENDAR_INFO m on a.CALENDAR_ID = m.CALENDAR_ID ) T where 1=1 and T.FINPRODTYPE = #{FINPROD_TYPE_TG_F06,jdbcType=VARCHAR}
and T.FINPRODID = #{finprodId,jdbcType=VARCHAR}
and T.FINPRODMARKETID LIKE CONCAT('%',CONCAT(#{finprodMarketId,jdbcType=VARCHAR},'%'))
and T.CCY = #{ccy,jdbcType=VARCHAR}
and T.VDATE between #{sDate} and #{eDate}
and T.TRADEMARKET = #{tradeMarket,jdbcType=VARCHAR}
and T.ISSUER = #{manager,jdbcType=VARCHAR}
and T.fundType = #{fundType,jdbcType=VARCHAR}
AND T.TYPE9 in
#{item}
AND T.TYPE10 in
#{item}
AND T.TYPE11 in
#{item}
and T.PAYTYPE = #{divideMethod,jdbcType=VARCHAR}
and T.PAYCYCLE = #{carryoverFreq,jdbcType=VARCHAR}
AND T.PURSPEED like concat(concat('%',#{purSpeed,jdbcType=VARCHAR}),'%')
AND T.REDSPEED like concat(concat('%',#{redSpeed,jdbcType=VARCHAR}),'%')
AND T.TRMFUNDTYPE in
#{item}

select ITEM_CODE as id , ITEM_VALUE as text from sys_datadict_list where 1=1 and DICT_CODE = #{dictCode,jdbcType=VARCHAR}
and (ITEM_CODE like concat('%',concat(#{trmFundType,jdbcType=VARCHAR},'%')) OR ITEM_VALUE like concat('%',concat(#{trmFundType,jdbcType=VARCHAR},'%')))
order by ORDER_NO ASC

SELECT CALENDAR_ID id, CALENDAR_NAME text FROM MST_CALENDAR_INFO
( CALENDAR_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR CALENDAR_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND CALENDAR_ID = #{calendarId}
